<template><div class="space-y-4"><div v-for="item in filters" :key="item.key"><label class="mb-1 block text-sm">{{ item.label }}: {{ item.value }}{{ item.unit }}</label><el-slider v-model="item.value" :min="item.min" :max="item.max"/></div><div class="rounded-xl p-8 text-center bg-gray-100 dark:bg-gray-700"><div class="mx-auto h-32 w-48 rounded-lg bg-gradient-to-r from-blue-500 to-purple-500" :style="{filter: filterValue}"/></div><el-input v-model="css" readonly/></div></template>
<script setup lang="ts">import { computed,ref } from 'vue';const filters=ref([{key:'blur',label:'模糊',value:0,min:0,max:20,unit:'px'},{key:'brightness',label:'亮度',value:100,min:0,max:200,unit:'%'},{key:'contrast',label:'对比度',value:100,min:0,max:200,unit:'%'},{key:'grayscale',label:'灰度',value:0,min:0,max:100,unit:'%'},{key:'saturate',label:'饱和度',value:100,min:0,max:200,unit:'%'}]);const filterValue=computed(()=>filters.value.map(x=>`${x.key}(${x.value}${x.unit})`).join(' '));const css=computed(()=>`filter: ${filterValue.value};`)</script>
